INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Cloud computing hosting arrangement implementation costs (ASU 2018-15)
(2, 'Intangible Assets', 'Meridian Corp. enters a 3-year cloud computing hosting arrangement in 2025 and incurs $95,000 in implementation costs: $30,000 evaluating vendors and $65,000 on configuration during the application development stage. Under ASU 2018-15, how should Meridian report these implementation costs?', '["Expense the entire $95,000 as incurred because Meridian does not control the software", "Capitalize $65,000 as a prepaid asset and expense $30,000; amortize the prepaid over the hosting term", "Capitalize the entire $95,000 as an intangible asset and amortize over the 3-year term", "Expense $65,000 and capitalize $30,000 because preliminary stage costs are more likely to benefit future periods"]'::jsonb, 1, 'Under ASU 2018-15 (codified in ASC 350-40), implementation costs of a hosting arrangement that is a service contract follow the same capitalization guidance as internal-use software. Application development stage costs ($65,000) are capitalized as a prepaid asset and amortized over the hosting term. Preliminary stage costs ($30,000) are expensed. Choice A incorrectly expenses all costs — ASU 2018-15 specifically allows capitalization of qualifying implementation costs even without software control.', 'medium', 3),

-- Q2: hard / L4 — Private entity goodwill amortization election (ASU 2014-02)
(2, 'Intangible Assets', 'Kelford Industries, a private company, acquires a competitor and recognizes $2,000,000 in goodwill. Management evaluates the ASU 2014-02 alternative to amortize goodwill over 10 years. Which statement best evaluates the financial reporting trade-offs of electing the goodwill amortization alternative?', '["Electing amortization eliminates all impairment testing requirements for goodwill", "The election creates a permanent book-tax difference because tax goodwill is not deductible", "Amortization reduces reported net income annually but simplifies impairment to a one-step triggering-event-only test, avoiding mandatory annual quantitative assessments", "The election is limited to goodwill from future acquisitions and cannot be applied to existing goodwill"]'::jsonb, 2, 'Under ASU 2014-02 (ASC 350-20-35), private companies may elect to amortize goodwill straight-line over 10 years or less. The trade-off is reduced net income from annual amortization expense offset by simplified impairment testing — only triggered by events, using a one-step quantitative test. Choice A is wrong because impairment testing is not eliminated; it is simplified to a triggering-event basis with an optional qualitative assessment.', 'hard', 4),

-- Q3: easy / L1 — Intangible asset identifiability criteria
(2, 'Intangible Assets', 'Under ASC 805, what criterion must an intangible asset meet to be recognized separately from goodwill in a business combination?', '["It must arise from contractual or legal rights, or be capable of being separated from the entity", "It must have a determinable useful life of 20 years or less", "It must be internally generated by the acquired entity", "It must have a readily determinable fair value quoted in an active market"]'::jsonb, 0, 'Under ASC 805-20-55, an intangible asset is identifiable if it meets either the contractual-legal criterion (arises from contractual or legal rights) or the separability criterion (can be separated and sold, transferred, licensed, or exchanged). Choice B is incorrect — there is no maximum useful life requirement for separate recognition; indefinite-life intangibles are also separately recognized if identifiable.', 'easy', 1),

-- Q4: medium / L2 — IPR&D completed vs abandoned treatment
(2, 'Intangible Assets', 'Hartwell Biotech acquired two in-process R&D projects in a 2024 business combination: Project Alpha ($1,200,000) and Project Beta ($600,000). In 2025, Project Alpha reaches completion while Project Beta is abandoned. Under ASC 350, how should Hartwell account for both projects in 2025?', '["Expense both projects totaling $1,800,000 as R&D costs", "Continue carrying both as indefinite-life intangible assets until the annual impairment test", "Reclassify both to finite-life intangible assets and begin amortization", "Reclassify Project Alpha as a finite-life intangible and begin amortization; write off Project Beta as an impairment loss"]'::jsonb, 3, 'Under ASC 350-30-35, IPR&D acquired in a business combination is classified as an indefinite-life intangible until the project is completed or abandoned. Upon completion, it becomes a finite-life asset subject to amortization. Upon abandonment, its carrying amount is written off as an impairment loss. Choice A incorrectly treats both as period R&D expense — acquired IPR&D is capitalized under ASC 805, not expensed.', 'medium', 2),

-- Q5: easy / L2 — Residual value of intangible assets
(2, 'Intangible Assets', 'Ashford Corp. acquires a patent for $200,000 with a 10-year useful life. Under ASC 350-30, what residual value should typically be assigned to a finite-life intangible asset?', '["10% of original cost, consistent with tangible asset conventions", "Zero, unless a third party has committed to purchase the asset at the end of its useful life or an active market exists", "Fair value at the end of useful life as estimated by management", "The amount recoverable through undiscounted future cash flows"]'::jsonb, 1, 'Under ASC 350-30-35-8, the residual value of a finite-life intangible asset is assumed to be zero unless a third party has committed to purchase the asset at the end of its useful life, or an active exchange market exists from which a residual value can be determined. Choice A is incorrect — there is no default 10% residual value assumption; the GAAP presumption is zero for intangibles.', 'easy', 2),

-- Q6: hard / L4 — GAAP vs IFRS intangible revaluation model comparison
(2, 'Intangible Assets', 'Thornbury Group reports under IFRS and holds a trademark carried at EUR 400,000 with a fair value of EUR 650,000. Its U.S. subsidiary holds an identical trademark under U.S. GAAP. Which statement best evaluates the reporting difference and its analytical implications?', '["Under IFRS, the trademark may be revalued to EUR 650,000 using the revaluation model if an active market exists, while U.S. GAAP requires the cost model, creating a comparability gap the analyst must adjust for", "Both IFRS and U.S. GAAP require the cost model for all intangible assets, so no adjustment is needed", "U.S. GAAP permits revaluation for indefinite-life intangibles only, so the analyst should verify the trademark''s useful life classification", "IFRS requires revaluation for all intangible assets, systematically overstating assets relative to U.S. GAAP"]'::jsonb, 0, 'Under IAS 38.75, entities may elect the revaluation model for intangible assets if an active market exists, carrying them at revalued amount. U.S. GAAP (ASC 350) requires the cost model only — no upward revaluation is permitted. Choice B is wrong because IFRS does offer the revaluation alternative. Choice D is wrong because IFRS permits but does not require the revaluation model; it remains an accounting policy election.', 'hard', 4),

-- Q7: easy / L1 — Definition of an intangible asset
(2, 'Intangible Assets', 'Under U.S. GAAP, which characteristic is required for an asset to qualify as an intangible asset?', '["The asset must have physical substance and generate monetary returns", "The asset must be acquired only through a business combination", "The asset must be identifiable, nonmonetary, and without physical substance", "The asset must have a useful life exceeding 20 years"]'::jsonb, 2, 'Under ASC 350-20-15, an intangible asset is an identifiable nonmonetary asset without physical substance. It must be identifiable (contractual-legal or separable) and lack physical form. Choice B is incorrect — intangible assets can also be acquired individually, in a group, or developed internally (e.g., software under ASC 350-40), not solely through business combinations.', 'easy', 1),

-- Q8: medium / L2 — Reclassification from indefinite to finite life
(2, 'Intangible Assets', 'Belmont Media holds a broadcast license classified as indefinite-life with a carrying amount of $1,500,000. In 2025, new legislation limits future renewals to a single 5-year extension. Under ASC 350, what accounting treatment is required?', '["Write down the license to fair value immediately without reclassification", "Reclassify the license as a finite-life intangible, test for impairment under ASC 360, and begin amortizing over the remaining useful life", "Continue classifying the license as indefinite-life because the extension has not yet been exercised", "Derecognize the license and recognize a new finite-life intangible at fair value"]'::jsonb, 1, 'Under ASC 350-30-35-16, when an indefinite-life intangible asset is reclassified as finite-life, the entity tests for impairment under ASC 360 at the carrying amount and then begins amortization over the remaining useful life. Choice C is incorrect because the legislative change makes the useful life determinable, triggering mandatory reclassification regardless of whether the extension has been exercised.', 'medium', 2),

-- Q9: medium / L2 — Bargain purchase (negative goodwill) gain recognition
(2, 'Intangible Assets', 'Preston Corp. acquires all net assets of Dover Inc. for $3,000,000. The fair value of Dover''s identifiable net assets totals $3,400,000. After reassessing all acquired assets and assumed liabilities, the $400,000 excess remains. Under ASC 805, how should Preston account for this difference?', '["Recognize a gain of $400,000 in the income statement in the period of acquisition", "Record $400,000 as negative goodwill on the balance sheet and amortize over the weighted-average life of acquired assets", "Reduce the fair values of noncurrent assets proportionally until the excess is eliminated", "Credit $400,000 to additional paid-in capital as part of the combination entry"]'::jsonb, 0, 'Under ASC 805-30-25-2, a bargain purchase occurs when the fair value of identifiable net assets exceeds consideration transferred. After reassessing all amounts, the acquirer recognizes the excess as a gain in earnings in the acquisition period. Choice B incorrectly describes the pre-SFAS 141R treatment (negative goodwill balance sheet item), which was eliminated. Choice C reflects the older APB 16 approach.', 'medium', 2),

-- Q10: medium / L3 — Software NRV write-down under ASC 985-20
(2, 'Intangible Assets', 'Crestwood Software has capitalized $800,000 of development costs for an external product under ASC 985-20. Cumulative amortization is $200,000, leaving unamortized cost of $600,000. Due to a competitor''s product launch, estimated net realizable value drops to $450,000. What amount should Crestwood report for this asset?', '["$800,000, the original capitalized cost", "$600,000, the unamortized cost before the NRV assessment", "$200,000, the excess of unamortized cost over NRV", "$450,000, because ASC 985-20 requires reporting at the lower of unamortized cost or net realizable value"]'::jsonb, 3, 'Under ASC 985-20-35-4, capitalized software costs for external sale are reported at the lower of unamortized cost or NRV at each balance sheet date. NRV ($450,000) is below unamortized cost ($600,000), so the asset is written down to $450,000 with a $150,000 charge to cost of sales. Choice B ignores the mandatory NRV ceiling test that distinguishes ASC 985-20 from internal-use software impairment under ASC 360.', 'medium', 3),

-- Q11: hard / L4 — Triggering events for interim goodwill impairment testing
(2, 'Intangible Assets', 'Glendale Holdings performed its annual goodwill impairment test on October 1, 2025, with no impairment found. On November 15, Glendale lost its largest customer representing 35% of the reporting unit''s revenue. The CFO argues no additional testing is needed until October 2026. Which statement best evaluates the CFO''s position?', '["The CFO is correct because goodwill impairment is tested only on the designated annual testing date", "The CFO is correct because the annual test already confirmed no impairment within the current fiscal year", "The CFO is incorrect; ASC 350-20-35-28 requires testing between annual dates when a triggering event makes it more likely than not that goodwill is impaired", "The CFO is incorrect because goodwill must be tested quarterly regardless of whether triggering events occur"]'::jsonb, 2, 'Under ASC 350-20-35-28, goodwill must be tested between annual tests when events or circumstances indicate it is more likely than not that the fair value of a reporting unit is below its carrying amount. Losing 35% of revenue is a significant triggering event. Choice A is wrong — the annual test is a minimum frequency, not a maximum. Choice D overstates the requirement; quarterly testing is not mandated.', 'hard', 4),

-- Q12: medium / L3 — Goodwill allocation on partial disposal of a reporting unit
(2, 'Intangible Assets', 'Pinnacle Corp. disposes of a business constituting 30% of a reporting unit. The reporting unit carries goodwill of $2,400,000. Under ASC 350-20-40, how should the goodwill associated with the disposed business be determined for calculating the gain or loss on disposal?', '["No goodwill is included because goodwill is only tested at the reporting unit level, not allocated to individual businesses", "Goodwill is allocated to the disposed business based on the relative fair values of the business disposed and the portion of the reporting unit retained", "The entire $2,400,000 of goodwill is derecognized when any part of a reporting unit is disposed", "Goodwill of $720,000 is allocated based on the 30% revenue proportion of the disposed business"]'::jsonb, 1, 'Under ASC 350-20-40-1, when a business within a reporting unit is disposed of, goodwill is included in the carrying amount of the disposed business for gain/loss purposes. The allocation uses relative fair values of the disposed portion and the retained portion. Choice D incorrectly uses revenue as the allocation basis — ASC 350-20-40 specifically requires relative fair value, not revenue or other operating metrics.', 'medium', 3),

-- Q13: medium / L2 — Franchise with renewal option at minimal cost → indefinite life
(2, 'Intangible Assets', 'Briarwood Restaurants acquires a franchise agreement for $500,000 with a 10-year initial term. The agreement includes successive renewal options at minimal cost, and Briarwood intends to renew indefinitely. Under ASC 350, how should this franchise right be classified?', '["Finite-life intangible amortized over 10 years, the initial contractual term", "Finite-life intangible amortized over 20 years reflecting one expected renewal", "Expense the $500,000 immediately because franchise rights cannot be capitalized", "Indefinite-life intangible that is not amortized but tested for impairment annually"]'::jsonb, 3, 'Under ASC 350-30-35-4, when an intangible asset''s contractual term can be renewed without substantial cost and renewal is expected, the useful life may be considered indefinite. Briarwood can renew at minimal cost and intends to do so, meaning no foreseeable limit exists on the cash-flow period. Choice A incorrectly limits the useful life to the initial term, ignoring the renewal analysis required by the standard.', 'medium', 2),

-- Q14: hard / L4 — Defensive intangible asset recognition in business combination
(2, 'Intangible Assets', 'Stonebridge Pharma acquires a competitor and identifies a patented drug formula it intends to shelve permanently to protect its own product. The patent has a fair value of $3,200,000 and 12 years remaining legal life. Staff argue the asset has no value since it will never generate revenue. Which statement best evaluates the proper treatment?', '["The patent must be recognized at $3,200,000 and amortized over its useful life from a market participant perspective, which considers defensive use as the highest and best use", "The patent should not be recognized because Stonebridge does not intend to use it to generate revenue", "The patent should be recognized at $3,200,000 then immediately impaired to zero because it produces no direct cash flows", "The patent''s value should be absorbed into goodwill because defensive assets are not separately identifiable"]'::jsonb, 0, 'Under ASC 820-10-35-10 and ASC 805-20-25, fair value reflects market participant assumptions, not the acquirer''s intended use. A defensive asset is valued at its highest and best use, which includes defensive use. The patent is identifiable via the contractual-legal criterion and must be recognized at fair value. Choice B incorrectly applies entity-specific intent rather than market participant assumptions required by ASC 820.', 'hard', 4),

-- Q15: hard / L4 — Goodwill allocation to multiple reporting units
(2, 'Intangible Assets', 'Wakefield Industries acquires Evergreen Corp. for $12,000,000 (identifiable net assets at fair value: $9,500,000, goodwill: $2,500,000). Evergreen will be integrated into two reporting units: Unit A (relative fair value 67%) and Unit B (relative fair value 33%). Under ASC 350-20-35, how should the goodwill be allocated?', '["$1,250,000 to each reporting unit equally", "The entire $2,500,000 to Unit A because it has the higher fair value", "$1,675,000 to Unit A and $825,000 to Unit B based on relative fair values of the reporting units expected to benefit", "Goodwill allocation is deferred until the first annual impairment test"]'::jsonb, 2, 'Under ASC 350-20-35-40, goodwill from a business combination is assigned to reporting units expected to benefit from the synergies. When multiple units benefit, allocation follows relative fair value: Unit A gets 67% x $2,500,000 = $1,675,000 and Unit B gets 33% x $2,500,000 = $825,000. Choice A incorrectly splits equally, ignoring the relative benefit analysis required by the standard.', 'hard', 4),

-- Q16: easy / L1 — Contract-based intangible asset example
(2, 'Intangible Assets', 'Which of the following is an example of a contract-based intangible asset recognized in a business combination under ASC 805?', '["Internally developed goodwill", "An assembled workforce", "A customer list developed through advertising campaigns", "A licensing agreement granting exclusive distribution rights"]'::jsonb, 3, 'Under ASC 805-20-55, a licensing agreement is a contract-based intangible asset because it arises from contractual or legal rights. Choice B (assembled workforce) fails both identifiability criteria — it is neither contractual-legal nor separable — so its value is subsumed into goodwill per ASC 805-20-55-6. Choice A cannot be recognized because internally generated goodwill is never capitalized.', 'easy', 1),

-- Q17: medium / L2 — Post-implementation costs for internal-use software
(2, 'Intangible Assets', 'Oakmont Systems completed its internal-use ERP system in January 2025. During the first year of use, Oakmont incurs $45,000 for employee training and $30,000 for routine maintenance. Under ASC 350-40, how should these post-implementation costs be treated?', '["Expense both costs as incurred because they are post-implementation stage activities", "Capitalize both costs because they extend the software''s useful life", "Capitalize the training costs and expense the maintenance costs", "Capitalize the maintenance costs and expense the training costs"]'::jsonb, 0, 'Under ASC 350-40-25-11, costs incurred during the post-implementation/operation stage — including training and routine maintenance — are expensed as incurred. Only costs during the application development stage qualify for capitalization. Choice B is incorrect because routine maintenance and training do not add significant functionality or extend the software''s useful life.', 'medium', 2),

-- Q18: easy / L1 — Indefinite life vs infinite life distinction
(2, 'Intangible Assets', 'Under ASC 350, what does classifying an intangible asset as having an indefinite useful life mean?', '["The asset will generate cash flows forever and never requires reassessment", "The asset''s useful life extends beyond 40 years by definition", "There is no foreseeable limit on the cash-flow-generating period, but the classification is reassessed each reporting period", "The asset cannot be sold, transferred, or licensed to another entity"]'::jsonb, 2, 'Under ASC 350-30-35-15, an indefinite-life classification means no foreseeable limit exists on the period the asset is expected to generate net cash flows. This classification must be reassessed each reporting period. Choice A confuses indefinite with infinite — indefinite does not mean permanent, and the standard explicitly requires periodic reassessment of the useful life determination.', 'easy', 1),

-- Q19: easy / L1 — Default amortization method for finite-life intangibles
(2, 'Intangible Assets', 'Under U.S. GAAP, what is the default amortization method for a finite-life intangible asset?', '["Double-declining balance over the estimated useful life", "Straight-line, unless another method better reflects the pattern of economic benefits consumed", "Units-of-production based on revenue generated each period", "Sum-of-the-years-digits over the estimated useful life"]'::jsonb, 1, 'Under ASC 350-30-35-6, a finite-life intangible shall be amortized using a method reflecting the pattern of economic benefit consumption. If that pattern cannot be reliably determined, straight-line is the default. Choice C is incorrect because revenue-based amortization is generally prohibited for intangible assets under ASU 2014-18, with only limited exceptions for specific circumstances.', 'easy', 1),

-- Q20: medium / L2 — Data conversion costs during application development stage
(2, 'Intangible Assets', 'Foxworth Corp. develops an internal-use inventory system. During the application development stage, it spends $180,000 on coding, $50,000 converting data from the legacy system, and $25,000 on testing. Under ASC 350-40, what total amount should Foxworth capitalize?', '["$180,000 — only coding costs qualify for capitalization", "$205,000 — testing costs must always be expensed", "$230,000 — data conversion costs are expensed as incurred", "$255,000 — coding, data conversion, and testing costs during the application development stage are all capitalizable"]'::jsonb, 3, 'Under ASC 350-40-25-7, capitalizable costs during the application development stage include coding, testing, and data conversion from legacy systems. All three ($180,000 + $50,000 + $25,000 = $255,000) qualify for capitalization. Choice C is incorrect — data conversion costs incurred during the application development stage are explicitly capitalizable under ASC 350-40, not expensed.', 'medium', 2),

-- Q21: medium / L2 — IPR&D impairment testing as indefinite-life asset
(2, 'Intangible Assets', 'Westbrook Pharma acquired in-process R&D for $2,500,000 in a business combination two years ago. The project remains incomplete. Under ASC 350, how should Westbrook test this asset for impairment?', '["As an indefinite-life intangible asset tested for impairment at least annually until the project is completed or abandoned", "As a finite-life intangible asset using the ASC 360 two-step recoverability test", "No impairment testing is required until the project reaches completion", "Using the goodwill impairment model at the reporting unit level"]'::jsonb, 0, 'Under ASC 350-30-35-17A, IPR&D acquired in a business combination is classified as an indefinite-life intangible and tested for impairment annually (or when triggering events occur) until the project is completed or abandoned. Choice B is incorrect because the ASC 360 finite-life recoverability test does not apply until the project is completed and reclassified as a finite-life intangible asset.', 'medium', 2),

-- Q22: medium / L3 — Hosting arrangement capitalized costs classified as prepaid
(2, 'Intangible Assets', 'Mercer Industries spends $120,000 on configuration and customization during implementation of a cloud-based CRM system. Mercer does not have the contractual right to take possession of the software. Under ASU 2018-15, how should the capitalized implementation costs be classified on the balance sheet?', '["As an intangible asset under ASC 350-40", "As property, plant, and equipment under ASC 360", "As a prepaid expense amortized over the hosting arrangement term", "Expensed immediately because Mercer does not control the underlying software"]'::jsonb, 2, 'Under ASU 2018-15, when a hosting arrangement is a service contract (customer cannot take possession of the software), capitalizable implementation costs are classified as a prepaid expense — not as intangible assets. The prepaid is amortized over the hosting term. Choice A is incorrect because ASC 350-40 intangible asset classification requires the customer to control the software through the right to take possession.', 'medium', 3),

-- Q23: easy / L1 — Internally generated brands expensed
(2, 'Intangible Assets', 'Under U.S. GAAP, how should costs of internally developing a brand name be accounted for?', '["Capitalized as an indefinite-life intangible asset", "Expensed as incurred because internally generated intangible assets other than certain software cannot be capitalized", "Capitalized and amortized over the estimated useful life of the brand", "Recognized at fair value on the balance sheet at each reporting date"]'::jsonb, 1, 'Under U.S. GAAP, costs of internally generated intangible assets — including brands, mastheads, and customer lists — are expensed as incurred. Only software development costs under ASC 985-20 and ASC 350-40 are exceptions permitting capitalization. Choice A is incorrect because capitalization of internally generated brands is expressly prohibited regardless of the useful life classification.', 'easy', 1),

-- Q24: easy / L1 — Goodwill recognized only in business combinations
(2, 'Intangible Assets', 'Under U.S. GAAP, when is goodwill recognized on the balance sheet?', '["Only when acquired in a business combination as the excess of purchase price over the fair value of identifiable net assets", "When internally generated goodwill is reliably measurable", "Whenever market capitalization exceeds book value of equity", "When management estimates the value of the entity''s reputation and synergies"]'::jsonb, 0, 'Under ASC 805-30-25-1, goodwill is recognized only in a business combination, measured as the excess of consideration transferred over the fair value of identifiable net assets acquired. Internally generated goodwill is never recognized. Choice C is incorrect — market capitalization exceeding book value may suggest unrecognized goodwill, but it does not trigger recognition under GAAP.', 'easy', 1),

-- Q25: easy / L1 — Noncompete agreement finite-life classification
(2, 'Intangible Assets', 'A noncompete agreement acquired in a business combination is classified as what type of intangible asset under U.S. GAAP?', '["An indefinite-life intangible that is not amortized", "Goodwill, because it cannot be separately sold", "An internally generated intangible expensed as incurred", "A finite-life intangible amortized over the contractual term"]'::jsonb, 3, 'A noncompete agreement is a contract-based intangible with a determinable useful life equal to its contractual term. Under ASC 350-30-35, it is classified as finite-life and amortized accordingly. Choice A is incorrect because the agreement has a defined expiration date, making the useful life determinable. Choice B is wrong because a noncompete meets the contractual-legal criterion for separate recognition from goodwill.', 'easy', 1),

-- Q26: hard / L3 — Goodwill impairment hierarchy with other long-lived assets
(2, 'Intangible Assets', 'Redfield Corp.''s reporting unit has a carrying amount of $8,000,000 including a customer list ($1,200,000), a patent ($800,000), equipment ($3,000,000), and goodwill ($3,000,000). The fair value of the reporting unit is $6,500,000. Under the impairment framework of ASC 350 and ASC 360, what goodwill impairment loss is recognized?', '["$1,500,000 allocated proportionally across all assets including goodwill", "Equipment is impaired first because tangible assets are tested before intangible assets under ASC 360", "$1,500,000 recognized entirely against goodwill because the shortfall does not exceed the $3,000,000 goodwill balance", "The customer list and patent are tested first under ASC 360 before any goodwill impairment is recognized"]'::jsonb, 2, 'Under ASC 350-20-35-3C, goodwill impairment equals the excess of carrying amount over fair value ($8,000,000 minus $6,500,000 = $1,500,000), capped at the goodwill balance ($3,000,000). Since $1,500,000 is less than $3,000,000, the entire loss is recognized against goodwill. Choice A incorrectly applies proportional allocation — the one-step goodwill test applies the shortfall to goodwill first, not across all assets.', 'hard', 3),

-- Q27: medium / L3 — Broadcast license with renewal history → indefinite life
(2, 'Intangible Assets', 'Stratford Media acquires a broadcast license for $750,000 with a 7-year initial term. The license has been renewed three times previously at minimal cost, and Stratford expects to renew indefinitely. Under ASC 350, what useful life classification is appropriate?', '["Finite-life of 7 years matching the initial contractual term", "Indefinite-life because the renewal history and minimal cost support no foreseeable limit on the cash-flow-generating period", "Finite-life of 28 years reflecting the sum of all prior and current terms", "Indefinite-life only until the first renewal period expires, then reassess"]'::jsonb, 1, 'Under ASC 350-30-35-4, when renewals are obtainable without substantial cost and the entity expects to renew, the useful life extends beyond the contractual term. A consistent history of renewal at minimal cost demonstrates no foreseeable limit, supporting indefinite-life classification. Choice A incorrectly limits the analysis to the initial contractual term without performing the renewal analysis required by the standard.', 'medium', 3),

-- Q28: medium / L2 — Intangible acquired in asset acquisition includes direct costs
(2, 'Intangible Assets', 'Dunmore Corp. purchases a patent from an unrelated third party for $340,000 cash plus $10,000 in directly attributable legal fees. The transaction does not qualify as a business combination. Under U.S. GAAP, at what amount should Dunmore initially recognize the patent?', '["$340,000 because legal fees are always period costs expensed as incurred", "$340,000 at fair value with legal fees recorded as a separate deferred charge", "$340,000 less estimated amortization for the partial year of acquisition", "$350,000 because directly attributable costs are included in the initial measurement of an acquired intangible asset"]'::jsonb, 3, 'Under ASC 350-30-25, an intangible asset acquired individually is initially measured at cost, including the purchase price plus directly attributable costs of preparing the asset for its intended use (legal fees, registration costs). Total cost is $340,000 + $10,000 = $350,000. Choice A is incorrect — unlike internally generated intangibles, acquired intangible assets capitalize transaction costs into their initial basis.', 'medium', 2),

-- Q29: medium / L3 — Amortization pattern reflecting economic benefit consumption
(2, 'Intangible Assets', 'Pemberton Corp. acquires a customer relationship intangible for $600,000 with a 10-year useful life. Historical data shows 60% of revenue from these customers occurs in years 1 through 4. Under ASC 350-30-35, what amortization method should Pemberton use?', '["An accelerated method reflecting the revenue pattern, because ASC 350-30 requires amortization to mirror the pattern of economic benefits consumed", "Straight-line over 10 years because U.S. GAAP prohibits accelerated amortization of intangible assets", "Units-of-revenue method recomputed annually based on actual revenue each period", "Straight-line over 4 years since the majority of benefits are consumed in the first 4 years"]'::jsonb, 0, 'Under ASC 350-30-35-6, amortization should reflect the pattern in which economic benefits are consumed. When historical data demonstrates front-loaded benefits (60% in years 1-4), an accelerated method is appropriate and required. Choice B is incorrect — GAAP does not prohibit accelerated amortization of intangibles; it merely defaults to straight-line when the consumption pattern cannot be reliably determined.', 'medium', 3),

-- Q30: medium / L3 — Substantial renewal cost limits useful life to contractual term
(2, 'Intangible Assets', 'Caldwell Energy holds a mineral extraction license acquired for $2,000,000 with a 20-year term. Caldwell has renewed three times previously at significant cost each time and plans to renew again. Under ASC 350-30-35, how should the substantial renewal costs affect the useful life determination?', '["The useful life includes all renewal periods regardless of cost because Caldwell has a history of successful renewals", "Renewal costs should be capitalized and added to the license cost, extending the useful life indefinitely", "The license should be reclassified as indefinite-life because Caldwell intends to renew perpetually", "The useful life is limited to the current contractual term because substantial renewal costs indicate renewals are not obtained without substantial cost under ASC 350-30-35"]'::jsonb, 3, 'Under ASC 350-30-35-5, renewal periods are included in the useful life only if renewals can be obtained without substantial cost. When significant costs are required each renewal, the ''without substantial cost'' condition fails, limiting the useful life to the current contractual term. Choice A is incorrect — renewal history alone is insufficient; the cost analysis under ASC 350-30-35 is the controlling factor for useful life determination.', 'medium', 3)

;

COMMIT;
